// Some portions generated by Claude
package org.eclipse.rdf4j.workbench.commands;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.Mockito.mock;

import java.util.List;
import java.util.Map;

import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.memory.MemoryStore;
import org.eclipse.rdf4j.workbench.util.CookieHandler;
import org.eclipse.rdf4j.workbench.util.WorkbenchPageProtocol;
import org.eclipse.rdf4j.workbench.util.WorkbenchRequest;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.mock.web.MockHttpServletRequest;
import org.springframework.mock.web.MockHttpServletResponse;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

/**
 * Saved queries' Edit (plan task M10.2) posts the saved query's parameters to the Query page; asked for page data, the
 * answer is the Query page with the query text, so the router can show it in place.
 */
class QueryServletEditPageDataTest {

	private static final ObjectMapper JSON_MAPPER = new ObjectMapper();

	private SailRepository repository;

	@BeforeEach
	void setUp() {
		repository = new SailRepository(new MemoryStore());
		repository.init();
	}

	@AfterEach
	void tearDown() {
		repository.shutDown();
	}

	@Test
	void editAnswersTheQueryPageWithTheTextEvenWithoutAResultLimit() throws Exception {
		MockHttpServletRequest raw = new MockHttpServletRequest("POST", "/query");
		raw.addHeader("Accept", WorkbenchPageProtocol.ACCEPT);
		raw.addParameter("action", "edit");
		raw.addParameter("queryLn", "SPARQL");
		raw.addParameter("query", "ASK { ?s ?p ?o }");
		raw.addParameter("ref", "text");
		raw.addParameter("owner", "");
		raw.addParameter("infer", "true");
		raw.addParameter("query-timeout", "");
		MockHttpServletResponse response = new MockHttpServletResponse();

		new CookieQueryServlet().doPost(new WorkbenchRequest(repository, raw, Map.of()), response);

		List<JsonNode> records = response.getContentAsString()
				.lines()
				.map(QueryServletEditPageDataTest::readTree)
				.toList();
		assertThat(records).extracting(record -> record.path("type").asText())
				.containsExactly("head", "view", "vars", "links", "rows", "end");
		assertThat(records.get(1).path("id").asText()).isEqualTo("query");
		JsonNode row = records.get(4).path("values").get(0);
		assertThat(row.get(1).path("value").asText()).isEqualTo("ASK { ?s ?p ?o }");
		assertThat(row.get(3).isNull()).as("no result limit was posted").isTrue();
	}

	private static JsonNode readTree(String line) {
		try {
			return JSON_MAPPER.readTree(line);
		} catch (Exception e) {
			throw new IllegalStateException(e);
		}
	}

	private static final class CookieQueryServlet extends QueryServlet {
		private CookieQueryServlet() {
			cookies = mock(CookieHandler.class);
		}
	}
}
